# Generates Str.h/.cpp + targets for the single-String-operand commands (ShowProp, HideProp, PlayAudioEffect, TimerTimeMessage).
use strict;
chdir "../../.." or die;
my $exe = do { local $/; open my $f, "<:raw", "Exported/SQZ.EXE" or die; <$f> };
sub rva2off { my ($va) = @_; my $pe = unpack('V', substr($exe,0x3c,4)); my ($nsec,$opt) = unpack('x6 v x12 v', substr($exe,$pe,24)); my $base = unpack('V', substr($exe,$pe+24+28,4));
  for my $i (0..$nsec-1) { my ($vs,$va0,$rs,$rp) = unpack('x8 V V V V', substr($exe,$pe+24+$opt+$i*40,40)); my $r = $va-$base; return $rp+$r-$va0 if $r >= $va0 && $r < $va0+$vs; } die }
sub cstr { return unpack('Z*', substr($exe, rva2off($_[0]), 64)); }
sub bytes { return substr($exe, rva2off($_[0]), $_[1]); }
my $q = '^' . chr(92) . '?'; my $bs = chr(92);
my (@h, @c, @t);
for my $sh (qw(ShowProp HideProp PlayAudioEffect TimerTimeMessage)) { my $short = $sh;
  my $n = "${short}Function";
  open R, "<tools/rtti.tsv"; my $row; while (<R>) { chomp; my @f = split /\t/; if ($f[0] eq ".?AV$n\@\@") { $row = [map { hex } split /;/, $f[4]]; last } }
  my ($sdd, $exec, $create, $print, $name) = @$row;
  my $nb = bytes($name, 6); my $str = cstr(unpack('V', substr($nb,1,4)));
  push @h, "class $n : public Function {\npublic:\n    virtual int Execute(ScriptCall *args, int extra);\n    virtual Function *Create(ArgList *list);\n    virtual void Print();\n    virtual const char *Name();\n    String text;                                         // 0x04\n};\n";
  push @c, "Function *$n\::Create(ArgList *list)\n{\n    $n *f = new $n;\n    f->text = ((StrArgList *)list)->ReadString(0);\n    return f;\n}\nvoid $n\::Print()\n{\n    DebugLog(\"%s %s\", Name(), text.c_str());\n" . ($short eq "TimerTimeMessage" ? "" : "    DebugLog(\"" . $bs . "n\");\n") . "}\nconst char *$n\::Name() { return \"$str\"; }\n";
  push @t, $q . "Create\@$n  " . sprintf("%x", $create) . " ${short}_create cc\n" . $q . "Print\@$n  " . sprintf("%x", $print) . " ${short}_print " . (($exec > $print && $exec - $print < 100) ? ($exec - $print) : "cc") . "\n" . $q . "Name\@$n  " . sprintf("%x", $name) . " ${short}_name 6\n" . $q . $bs . "?_G$n  " . sprintf("%x", $sdd) . " ${short}_sdd cc\n";
}
open H, ">Repo/bm/FunctionStr/Str.h"; print H "// Script commands whose only operand is a name (generated by gen.pl).\n#pragma once\n#include \"FunctionArgs/FunctionArgs.h\"\n\nstruct StrArgList {\n    virtual String ReadString(int flag);   // slot 0\n};\n\n", join("\n", @h); close H;
open C, ">Repo/bm/FunctionStr/Str.cpp"; print C "// Small slots of the single-name commands (generated by gen.pl).\n#include \"FunctionStr/Str.h\"\n\n", join("\n", @c); close C;
open T, ">Repo/bm/FunctionStr/targets.txt"; print T @t; close T;
